// src/index.js
import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";
import { FRONT_BASE } from './api/config';

(async function bootstrap() {
  const base = (FRONT_BASE || "/").replace(/\/+$/, ""); // ex) "/woodenpages" 또는 ""
  const isLocal = location.hostname === "localhost" || location.hostname === "127.0.0.1";

  // 로컬: 루트 스코프로 등록
  const swUrl   = isLocal ? "/mockServiceWorker.js"       : `${base}/mockServiceWorker.js`;
  const swScope = isLocal ? "/"                           : `${base}/`;

  await worker.start({
    serviceWorker: { url: swUrl, options: { scope: swScope } },
    onUnhandledRequest: "warn",
  });
  console.log("[MSW] registered:", { url: swUrl, scope: swScope });

  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();
